package main

// Each page defines body before the shared document. Keeping templates as constants
// preserves the existing render(w, pageTemplate, data) call sites.
const base = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#0b1020"><title>RadiusStack · Identity Sync</title>
<style>
:root{color-scheme:dark;--bg:#090e1a;--sidebar:#0e1525;--panel:#111a2b;--raised:#172238;--border:#26334b;--text:#f0f4fc;--muted:#9baac2;--subtle:#7183a0;--blue:#52a9ff;--cyan:#38d9d0;--green:#4ed5a4;--red:#ff8692;--radius:13px}
*{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:radial-gradient(ellipse 85% 65% at 80% -20%,#173055 0%,transparent 70%),var(--bg);color:var(--text);font:14px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.55;cursor:not-allowed}:focus-visible{outline:2px solid var(--cyan);outline-offset:3px}::selection{background:#225c89;color:#fff}.app{min-height:100vh;display:grid;grid-template-columns:238px minmax(0,1fr)}.sidebar{position:sticky;top:0;height:100vh;display:flex;flex-direction:column;padding:26px 14px;background:linear-gradient(180deg,#10192b,#0d1423);border-right:1px solid var(--border)}.brand{display:flex;align-items:center;gap:11px;padding:4px 10px 27px;color:var(--text);font-size:17px;font-weight:750;letter-spacing:-.04em}.brand:hover{text-decoration:none}.brandmark{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:linear-gradient(135deg,#54a9ff,#36ddcc);color:#071724;font-size:20px;font-weight:900;box-shadow:0 0 24px #298be947}.brand small{display:block;color:var(--subtle);font-size:10px;letter-spacing:.14em;font-weight:700;text-transform:uppercase;line-height:1.1}.nav-label{margin:5px 12px 12px;font-size:10px;text-transform:uppercase;letter-spacing:.16em;color:var(--subtle);font-weight:750}.nav{display:grid;gap:4px}.nav a{display:flex;align-items:center;gap:11px;padding:10px 12px;border:1px solid transparent;border-radius:9px;color:var(--muted);font-weight:560;transition:background .15s,color .15s}.nav a:hover{background:#ffffff0b;color:var(--text);text-decoration:none}.nav a[aria-current=page]{background:linear-gradient(90deg,#1d4061,#172740);border-color:#32618a;color:#eff8ff;box-shadow:inset 3px 0 var(--cyan)}.nav .icon{width:20px;text-align:center;font-size:16px;color:var(--blue)}.side-bottom{margin-top:auto;padding:15px 10px 2px;border-top:1px solid var(--border);color:var(--subtle);font-size:12px}.side-bottom a{display:inline-block;margin-top:9px;color:var(--muted)}.main{min-width:0;padding:31px clamp(18px,4vw,56px) 70px;max-width:1600px;width:100%;margin:0 auto}.topline{display:flex;justify-content:space-between;align-items:center;gap:14px;margin-bottom:32px;color:var(--subtle);font-size:12px}.topline strong{color:var(--muted);font-weight:600}.topline .crumb{letter-spacing:.03em}.live{display:inline-flex;align-items:center;gap:8px;border:1px solid #2c5b58;background:#12363255;border-radius:99px;color:#91e8d2;padding:5px 11px;white-space:nowrap}.dot{height:7px;width:7px;border-radius:50%;background:var(--green);box-shadow:0 0 9px var(--green)}.pagehead{margin-bottom:26px}.eyebrow{color:var(--cyan);text-transform:uppercase;letter-spacing:.18em;font-size:11px;font-weight:800;margin:0 0 8px}h1{font-size:clamp(26px,3vw,36px);letter-spacing:-.045em;line-height:1.15;margin:0 0 10px;font-weight:750}h2{font-size:17px;letter-spacing:-.025em;margin:0 0 5px}h3{font-size:14px;margin:0 0 6px}.pagehead p,.muted{color:var(--muted);margin:0}.pagehead p{max-width:68ch}.grid{display:grid;gap:18px}.two{grid-template-columns:repeat(2,minmax(0,1fr))}.three{grid-template-columns:repeat(3,minmax(0,1fr))}.card{min-width:0;padding:22px;background:linear-gradient(155deg,#172238,#111a2b 70%);border:1px solid var(--border);border-radius:var(--radius);box-shadow:0 12px 35px #0000001a}.card+.card,.section{margin-top:18px}.card-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:18px}.card-head p{margin:3px 0 0;color:var(--muted)}.card-head .badge{flex-shrink:0}.badge{display:inline-flex;align-items:center;padding:4px 9px;border-radius:100px;border:1px solid #336a79;color:#a5eaf1;background:#16465738;font-size:11px;font-weight:700;letter-spacing:.03em}.badge.good{color:#8be5c1;border-color:#295b50;background:#15433752}.badge.quiet{color:var(--muted);border-color:var(--border);background:#ffffff07}.badge.warn{color:#ffd195;border-color:#765533;background:#51391d40}.stat{font-size:38px;font-weight:750;line-height:1.1;letter-spacing:-.06em;margin:8px 0}.stat-label{color:var(--muted);font-size:12px;font-weight:600;letter-spacing:.02em}.divider{height:1px;background:var(--border);margin:21px 0}.actions{display:flex;flex-wrap:wrap;gap:9px;align-items:center}.button,button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:37px;padding:8px 13px;border-radius:8px;border:1px solid #3b84b5;background:linear-gradient(180deg,#287bb3,#206394);color:#fff;font-size:13px;font-weight:650;line-height:1.2;box-shadow:0 1px 0 #ffffff22 inset;white-space:normal;text-align:center}.button:hover,button:hover{background:#328ac2;text-decoration:none}.button.secondary,button.secondary{background:#1a2940;border-color:#354966;color:#dceafb}.button.secondary:hover,button.secondary:hover{background:#233852}.button.danger,button.danger{border-color:#67404a;background:#46262d;color:#ffc4c8}.button.danger:hover,button.danger:hover{background:#62323c}.button.ghost,button.ghost{background:transparent;border-color:var(--border);color:var(--muted)}.button.small,button.small{min-height:31px;padding:6px 9px;font-size:12px}.field{display:grid;gap:6px;min-width:0}.field>label,.field>span{font-weight:650;color:#d9e5f7;font-size:12px}.hint{color:var(--subtle);font-size:11px;line-height:1.45;margin:0}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.full{grid-column:1/-1}input:not([type=checkbox]):not([type=file]),select,textarea{width:100%;min-width:0;min-height:39px;border:1px solid #374860;border-radius:8px;background:#0d1728;color:var(--text);padding:9px 11px;outline:none}input:not([type=checkbox]):not([type=file]):focus,select:focus,textarea:focus{border-color:var(--blue);box-shadow:0 0 0 3px #4c9fec27}input::placeholder,textarea::placeholder{color:#7689a4}input[type=file]{max-width:100%;padding:9px;border:1px dashed #42647c;border-radius:8px;color:var(--muted)}input[type=checkbox]{accent-color:#3da9df;width:17px;height:17px;margin:0;vertical-align:middle}.check{display:flex;align-items:flex-start;gap:9px;color:var(--muted);font-size:13px;cursor:pointer}.form-actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:22px}.table-wrap{overflow-x:auto;border:1px solid var(--border);border-radius:10px}table{border-collapse:collapse;width:100%;min-width:560px;font-size:13px}th{text-transform:uppercase;font-size:10px;letter-spacing:.12em;font-weight:750;color:var(--subtle);background:#101b2d}td,th{padding:13px 15px;text-align:left;border-bottom:1px solid #26334b;vertical-align:middle}tr:last-child td{border-bottom:0}tbody tr:hover{background:#ffffff05}td .actions{gap:6px}.mono,code,pre{font-family:ui-monospace,SFMono-Regular,Consolas,"Liberation Mono",monospace}code{color:#a1def1;font-size:12px}.status{max-width:320px;overflow-wrap:anywhere;color:var(--muted)}.notice{border:1px solid #3d6475;background:#15314489;color:#c8e9f7;padding:11px 14px;border-radius:9px;margin:0 0 20px;overflow-wrap:anywhere}.empty{padding:32px;text-align:center;color:var(--muted);border:1px dashed #344862;border-radius:10px}.empty strong{display:block;color:var(--text);margin-bottom:3px}.stack{display:grid;gap:14px}.inline-form{display:inline-flex;align-items:center;gap:7px;flex-wrap:wrap}.inline-form .check{font-size:11px}.footer{margin-top:37px;color:var(--subtle);font-size:11px}.log{height:min(55vh,520px);min-height:220px;overflow:auto;margin:0;padding:18px;border:1px solid #293c55;border-radius:10px;background:#080f1c;color:#a8d7ec;line-height:1.7;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.log-line{display:block;border-bottom:1px solid #ffffff0c;padding:2px 0}.log-line:last-child{border:0}.login-layout{min-height:100vh;display:grid;place-items:center;padding:25px;background:radial-gradient(circle at 48% 15%,#204276 0,transparent 35%),var(--bg)}.login-box{width:min(100%,430px)}.login-brand{display:flex;justify-content:center;margin-bottom:31px}.login-brand .brand{padding:0}.login-box .card{padding:32px}.login-box h1{font-size:27px}.login-box .field{margin:15px 0}.login-box button{width:100%;margin-top:9px}.login-foot{text-align:center;margin-top:23px;color:var(--subtle);font-size:12px}
@media(max-width:1000px){.app{grid-template-columns:190px minmax(0,1fr)}.sidebar{padding-inline:10px}.main{padding:25px 22px 55px}.two,.three{grid-template-columns:1fr}}
@media(max-width:690px){.app{display:block}.sidebar{position:relative;height:auto;padding:13px 15px 10px;border-right:0;border-bottom:1px solid var(--border)}.brand{padding:0 0 12px}.nav-label,.side-bottom{display:none}.nav{display:flex;overflow-x:auto;gap:5px;padding-bottom:2px;scrollbar-width:thin}.nav a{flex-shrink:0;padding:8px 10px;font-size:12px}.nav .icon{display:none}.main{padding:20px 15px 45px}.topline{margin-bottom:23px}.fields{grid-template-columns:1fr}.card{padding:17px}.pagehead{margin-bottom:20px}.table-wrap{margin:0 -2px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}
</style></head><body>{{template "body" .}}</body></html>
{{define "nav"}}<aside class="sidebar"><a class="brand" href="/"><span class="brandmark" aria-hidden="true">R</span><span>RadiusStack<small>Identity Sync</small></span></a><div class="nav-label">Workspace</div><nav class="nav" aria-label="Primary navigation">
<a href="/" {{if eq . "dashboard"}}aria-current="page"{{end}}><span class="icon" aria-hidden="true">◫</span>Dashboard</a>
<a href="/settings" {{if eq . "settings"}}aria-current="page"{{end}}><span class="icon" aria-hidden="true">⚙</span>Settings</a>
<a href="/firewalls" {{if eq . "firewalls"}}aria-current="page"{{end}}><span class="icon" aria-hidden="true">⬡</span>Firewalls</a>
<a href="/manual" {{if eq . "manual"}}aria-current="page"{{end}}><span class="icon" aria-hidden="true">⌘</span>Manual IDs</a>
<a href="/debug" {{if eq . "debug"}}aria-current="page"{{end}}><span class="icon" aria-hidden="true">≡</span>Debug log</a>
<a href="/admins" {{if eq . "admin"}}aria-current="page"{{end}}><span class="icon" aria-hidden="true">♙</span>Administrators</a>
<a href="/stats" {{if eq . "stats"}}aria-current="page"{{end}}><span class="icon" aria-hidden="true">▥</span>Statistics</a>
<a href="/config" {{if eq . "config"}}aria-current="page"{{end}}><span class="icon" aria-hidden="true">⇄</span>Config</a>
</nav><div class="side-bottom"><span class="live"><span class="dot"></span> Console active</span><br><a href="/logout">Sign out →</a></div></aside>{{end}}
{{define "top"}}<div class="topline"><span class="crumb">RadiusStack <span aria-hidden="true">/</span> Identity Sync <span aria-hidden="true">/</span> <strong>{{.}}</strong></span><span class="live"><span class="dot"></span> Management console</span></div>{{end}}`

const loginT = `{{define "body"}}<main class="login-layout"><div class="login-box"><div class="login-brand"><div class="brand"><span class="brandmark" aria-hidden="true">R</span><span>RadiusStack<small>Identity Sync</small></span></div></div><div class="card"><p class="eyebrow">Secure access</p><h1>Welcome back</h1><p class="muted">Sign in to manage identity synchronization.</p>{{if .Error}}<p class="notice" role="alert">{{.Error}}</p>{{end}}<form action="/login" method="post"><div class="field"><label for="username">Username</label><input id="username" name="username" autocomplete="username" required autofocus></div><div class="field"><label for="password">Password</label><input id="password" type="password" name="password" autocomplete="current-password" required></div><button type="submit">Sign in →</button></form></div><p class="login-foot">RadiusStack · Identity orchestration</p></div></main>{{end}}` + base

const homeT = `{{define "body"}}<div class="app">{{template "nav" "dashboard"}}<main class="main">{{template "top" "Dashboard"}}<header class="pagehead"><p class="eyebrow">Overview</p><h1>Identity Sync</h1><p>Welcome back, {{.User.Username}}. Monitor active mappings and keep your firewalls in sync with RadiusStack.</p></header>{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}<div class="grid three"><section class="card"><span class="stat-label">Tracked identities</span><div class="stat">{{.Count}}</div><span class="badge good">Managed mappings</span></section><section class="card"><span class="stat-label">Configured firewalls</span><div class="stat">{{len .FW}}</div><span class="badge">Identity integrations</span></section><section class="card"><span class="stat-label">Synchronization</span><h2 style="margin:16px 0 11px">Ready on demand</h2><form action="/sync" method="post"><button type="submit">↻ &nbsp;Synchronize now</button></form></section></div><section class="card section"><div class="card-head"><div><h2>Firewall health</h2><p>Last reported state for each configured gateway.</p></div><a class="button secondary small" href="/firewalls">Manage firewalls →</a></div>{{if .FW}}<div class="table-wrap"><table><thead><tr><th>Gateway</th><th>Vendor</th><th>Address</th><th>Last status</th><th>Last sync</th></tr></thead><tbody>{{range .FW}}<tr><td><strong>{{.Name}}</strong></td><td>{{.Vendor}}</td><td><code>{{.Address}}</code></td><td class="status">{{if .LastStatus}}{{.LastStatus}}{{else}}Not yet synchronized{{end}}</td><td class="muted">{{if .LastSync.IsZero}}—{{else}}{{.LastSync.Format "2006-01-02 15:04 UTC"}}{{end}}</td></tr>{{end}}</tbody></table></div>{{else}}<div class="empty"><strong>No firewalls configured</strong>Add your first gateway to start managing identities.</div>{{end}}</section><footer class="footer">RadiusStack Identity Sync · Secure management console</footer></main></div>{{end}}` + base

const settingsT = `{{define "body"}}<div class="app">{{template "nav" "settings"}}<main class="main">{{template "top" "Settings"}}<header class="pagehead"><p class="eyebrow">Connections & schedules</p><h1>Settings</h1><p>Configure the RadiusStack session source, RADIUS authentication, and polling intervals.</p></header>{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}<form action="/settings" method="post"><section class="card"><div class="card-head"><div><h2>RadiusStack API</h2><p>Pull active sessions to generate identity mappings.</p></div><span class="badge">Source</span></div><div class="fields"><div class="field full"><label for="radius_url">API base URL</label><input id="radius_url" name="radius_url" type="url" placeholder="https://radius.example.com" value="{{.C.RadiusURL}}"></div><div class="field"><label for="radius_api_key">API key</label><input id="radius_api_key" name="radius_api_key" type="password" autocomplete="new-password" placeholder="Leave blank to keep existing key"><p class="hint">Write-only; enter a value only to replace it.</p></div><div class="field"><label for="tenant_id">Tenant ID</label><input id="tenant_id" name="tenant_id" placeholder="Optional" value="{{.C.TenantID}}"></div><label class="check full"><input type="checkbox" name="radius_verify_tls" {{if .C.VerifyTLS}}checked{{end}}>Verify RadiusStack server certificate</label></div></section><section class="card"><div class="card-head"><div><h2>RADIUS authentication & accounting</h2><p>Authenticate defined administrators and report accounting sessions.</p></div><span class="badge quiet">Access</span></div><div class="fields"><div class="field"><label for="radius_host">RADIUS host</label><input id="radius_host" name="radius_host" placeholder="Host or IP address" value="{{.C.RadiusHost}}"></div><div class="field"><label for="radius_secret">Shared secret</label><input id="radius_secret" name="radius_secret" type="password" autocomplete="new-password" placeholder="Leave blank to keep existing secret"><p class="hint">Write-only; never displayed after saving.</p></div><div class="field"><label for="radius_auth_port">Authentication port</label><input id="radius_auth_port" name="radius_auth_port" type="number" min="1" max="65535" value="{{.C.RadiusAuthPort}}"></div><div class="field"><label for="radius_acct_port">Accounting port</label><input id="radius_acct_port" name="radius_acct_port" type="number" min="1" max="65535" value="{{.C.RadiusAcctPort}}"></div></div></section><section class="card"><div class="card-head"><div><h2>Synchronization intervals</h2><p>Control incremental polls, full refreshes, and interim accounting.</p></div><span class="badge quiet">Timing</span></div><div class="fields three"><div class="field"><label for="poll_seconds">Poll interval · seconds</label><input id="poll_seconds" name="poll_seconds" type="number" min="5" value="{{.C.PollSeconds}}"></div><div class="field"><label for="full_minutes">Full resync · minutes</label><input id="full_minutes" name="full_minutes" type="number" min="1" value="{{.C.FullMinutes}}"></div><div class="field"><label for="interim_seconds">Accounting interim · seconds</label><input id="interim_seconds" name="interim_seconds" type="number" min="10" value="{{.C.InterimSeconds}}"></div></div><div class="form-actions"><button type="submit">Save settings</button></div></section></form><section class="card"><div class="card-head"><div><h2>Connection check</h2><p>Test the current saved RadiusStack API configuration.</p></div></div><form action="/test/radius" method="post"><button class="secondary" type="submit">Test RadiusStack API</button></form></section><footer class="footer">Changes to credentials are only applied when a new value is supplied.</footer></main></div>{{end}}` + base

const fwT = `{{define "body"}}<div class="app">{{template "nav" "firewalls"}}<main class="main">{{template "top" "Firewalls"}}<header class="pagehead"><p class="eyebrow">Gateways</p><h1>Firewalls</h1><p>Connect supported identity sources and inspect synchronization health.</p></header>{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}<section class="card"><div class="card-head"><div><h2>Add a firewall</h2><p>Choose the exact integration product; see the deployment README for credentials and prerequisites.</p></div><span class="badge">New gateway</span></div><form action="/firewalls" method="post"><div class="fields"><div class="field"><label for="fw_name">Friendly name</label><input id="fw_name" name="name" placeholder="Production gateway" required></div><div class="field"><label for="vendor">Vendor</label><select id="vendor" name="vendor"><option value="checkpoint">Check Point · Identity Web API</option><option value="paloalto">Palo Alto · PAN-OS User-ID</option><option value="cisco">Cisco · ISE-PIC API Provider (requires ISE-PIC)</option><option value="watchguard">WatchGuard · Firebox RSSO (RADIUS accounting)</option><option value="sonicwall">SonicWall · SonicOS third-party SSO</option><option value="fortigate">Fortinet · FortiGate RSSO (RADIUS accounting)</option><option value="fortinet">Fortinet · FortiAuthenticator FSSO</option><option value="forcepoint">Forcepoint · User ID Service</option></select></div><div class="field"><label for="fw_address">Gateway IP or FQDN</label><input id="fw_address" name="address" placeholder="gateway.example.com" required></div><div class="field"><label for="fw_secret">Integration credential / shared secret</label><input id="fw_secret" name="secret" type="password" autocomplete="new-password" placeholder="See integration credential format in README" required></div><label class="check full"><input type="checkbox" name="verify_tls" checked>Verify HTTPS server certificate (turn off only for a trusted private/self-signed CA exception)</label></div><div class="form-actions"><button type="submit">＋ Add firewall</button></div></form></section><section class="card"><div class="card-head"><div><h2>Configured gateways</h2><p>Test connectivity or manage mappings per gateway.</p></div><span class="badge quiet">{{len .FW}} total</span></div>{{if .FW}}<div class="table-wrap"><table><thead><tr><th>Gateway</th><th>Address</th><th>Status</th><th>Actions</th></tr></thead><tbody>{{range .FW}}<tr><td><strong>{{.Name}}</strong><br><small class="muted">{{.Vendor}} {{if .Enabled}}· Enabled{{else}}· Disabled{{end}}</small></td><td><code>{{.Address}}</code></td><td class="status">{{if .LastStatus}}{{.LastStatus}}{{else}}Not yet synchronized{{end}}{{if not .LastSync.IsZero}}<br><small>{{.LastSync.Format "2006-01-02 15:04 UTC"}}</small>{{end}}</td><td><div class="stack"><form class="inline-form" action="/test/firewall" method="post"><input type="hidden" name="id" value="{{.ID}}"><small class="muted">{{if eq .Vendor "watchguard"}}RADIUS/UDP{{else if eq .Vendor "fortigate"}}RADIUS/UDP{{else}}{{if .VerifyTLS}}TLS verified{{else}}TLS verification disabled{{end}}{{end}}</small><button class="secondary small" type="submit">Read-only test</button></form><div class="actions"><a class="button secondary small" href="/firewall/identities?id={{.ID}}" target="_blank" rel="noopener">View identities ↗</a><form action="/firewall/mappings/delete" method="post" onsubmit="return confirm('Delete all managed mappings from this firewall?')"><input type="hidden" name="id" value="{{.ID}}"><button class="danger small" type="submit">Clear mappings</button></form><form action="/firewall/delete" method="post" onsubmit="return confirm('Remove this firewall configuration?')"><input type="hidden" name="id" value="{{.ID}}"><button class="ghost small" type="submit">Remove</button></form></div></div></td></tr>{{end}}</tbody></table></div>{{else}}<div class="empty"><strong>No firewalls yet</strong>Add a gateway above to begin synchronization.</div>{{end}}</section></main></div>{{end}}` + base

const manualT = `{{define "body"}}<div class="app">{{template "nav" "manual"}}<main class="main">{{template "top" "Manual identities"}}<header class="pagehead"><p class="eyebrow">Overrides</p><h1>Manual identities</h1><p>Pin specific IP addresses to usernames alongside the RadiusStack session feed.</p></header>{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}<section class="card"><div class="card-head"><div><h2>Add identities</h2><p>Enter one or more IPv4 address / username pairs.</p></div></div><form action="/manual" method="post"><div id="manual-rows" class="stack"><div class="fields"><div class="field"><label for="manual-ip-0">IP address</label><input id="manual-ip-0" name="ip" placeholder="192.0.2.10" inputmode="decimal" required></div><div class="field"><label for="manual-user-0">Username</label><input id="manual-user-0" name="username" placeholder="alice" required></div></div></div><div class="form-actions"><button class="secondary" id="add-manual-row" type="button">＋ Add another row</button><button type="submit">Save identities</button></div></form></section><section class="card"><div class="card-head"><div><h2>Saved overrides</h2><p>These mappings take precedence over discovered sessions.</p></div><span class="badge quiet">{{len .Items}} entries</span></div>{{if .Items}}<div class="table-wrap"><table><thead><tr><th>IP address</th><th>Username</th><th>Actions</th></tr></thead><tbody>{{range .Items}}<tr><td><code>{{.IP}}</code></td><td><form id="edit-manual-{{.IP}}" action="/manual" method="post"><input type="hidden" name="ip" value="{{.IP}}"><label class="field"><span class="hint">Username</span><input name="username" value="{{.Username}}" required></label></form></td><td><div class="actions"><button class="secondary small" type="submit" form="edit-manual-{{.IP}}">Save</button><form action="/manual/delete" method="post" onsubmit="return confirm('Delete this manual identity?')"><input type="hidden" name="ip" value="{{.IP}}"><button class="danger small" type="submit">Delete</button></form></div></td></tr>{{end}}</tbody></table></div>{{else}}<div class="empty"><strong>No manual identities</strong>Add an override above when a mapping needs to be pinned.</div>{{end}}</section><script>(function(){var rows=document.getElementById('manual-rows'),button=document.getElementById('add-manual-row');button.addEventListener('click',function(){var n=rows.children.length,div=document.createElement('div');div.className='fields';div.innerHTML='<div class="field"><label for="manual-ip-'+n+'">IP address</label><input id="manual-ip-'+n+'" name="ip" placeholder="192.0.2.10" inputmode="decimal" required></div><div class="field"><label for="manual-user-'+n+'">Username</label><input id="manual-user-'+n+'" name="username" placeholder="alice" required></div>';rows.appendChild(div);div.querySelector('input').focus()})})()</script></main></div>{{end}}` + base

const debugT = `{{define "body"}}<div class="app">{{template "nav" "debug"}}<main class="main">{{template "top" "Debug log"}}<header class="pagehead"><p class="eyebrow">Diagnostics</p><h1>Debug log</h1><p>Review recent API activity and synchronization events. Sensitive credentials are not shown.</p></header>{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}<section class="card"><div class="card-head"><div><h2>Logging controls</h2><p>Enable verbose entries only while troubleshooting.</p></div>{{if .Enabled}}<span class="badge good">Enabled</span>{{else}}<span class="badge quiet">Disabled</span>{{end}}</div><form action="/debug" method="post" class="actions"><label class="field" for="log-limit"><span>Lines to show</span><select id="log-limit" name="limit"><option value="50" {{if eq .Limit 50}}selected{{end}}>50</option><option value="100" {{if eq .Limit 100}}selected{{end}}>100</option><option value="200" {{if or (not .Limit) (eq .Limit 200)}}selected{{end}}>200</option><option value="500" {{if eq .Limit 500}}selected{{end}}>500</option></select></label><button class="secondary" name="enabled" value="true" type="submit">Enable debug</button><button class="ghost" name="enabled" value="false" type="submit">Disable debug</button></form></section><section class="card"><div class="card-head"><div><h2>Recent events</h2><p>Newest entries are shown first.</p></div><div class="actions"><label class="check"><input id="follow-log" type="checkbox">Follow new entries</label><button class="secondary small" id="refresh-log" type="button">Refresh</button></div></div><div id="debug-log" class="log" role="log" aria-label="Debug events" aria-live="off">{{if .Lines}}{{range .Lines}}<span class="log-line">{{.}}</span>{{end}}{{else}}<span class="muted">No debug events yet. Enable logging to capture future activity.</span>{{end}}</div><p class="hint" style="margin-top:12px">Showing up to {{if .Limit}}{{.Limit}}{{else}}200{{end}} recent entries. Auto-refresh uses <code>/debug/tail</code> while Follow is enabled.</p></section><script>(function(){var box=document.getElementById('debug-log'),follow=document.getElementById('follow-log'),refresh=document.getElementById('refresh-log'),busy=false;async function update(){if(busy)return;busy=true;try{var r=await fetch('/debug/tail?limit='+encodeURIComponent(document.getElementById('log-limit').value),{headers:{'Accept':'application/json'},cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);var ct=r.headers.get('content-type')||'',content=ct.indexOf('json')>=0?await r.json():await r.text();if(Array.isArray(content))content=content.map(function(row){return typeof row==='string'?row:(row.created||row.Created||'')+' '+(row.message||row.Message||'')}).join('\n');else if(content&&typeof content==='object')content=Array.isArray(content.lines)?content.lines.join('\n'):JSON.stringify(content);box.textContent=String(content||'No debug events yet.');box.scrollTop=box.scrollHeight}catch(e){console.warn('Debug refresh unavailable:',e)}finally{busy=false}}refresh.addEventListener('click',update);setInterval(function(){if(follow.checked)update()},5000);follow.addEventListener('change',function(){if(follow.checked)update()})})()</script></main></div>{{end}}` + base

const adminT = `{{define "body"}}<div class="app">{{template "nav" "admin"}}<main class="main">{{template "top" "Administrators"}}<header class="pagehead"><p class="eyebrow">Access control</p><h1>Administrators</h1><p>Manage local and RADIUS-backed console users and their active sessions.</p></header>{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}<section class="card"><div class="card-head"><div><h2>Add administrator</h2><p>RADIUS users must be explicitly defined before they can sign in.</p></div><span class="badge">New user</span></div><form action="/admins" method="post"><div class="fields"><div class="field"><label for="admin_username">Username</label><input id="admin_username" name="username" autocomplete="off" required></div><div class="field"><label for="admin_mode">Authentication</label><select id="admin_mode" name="mode"><option value="local">Local password</option><option value="radius">RADIUS authentication</option></select></div><div class="field full" id="admin-password-field"><label for="admin_password">Local password</label><input id="admin_password" name="password" type="password" autocomplete="new-password" minlength="8" required><p class="hint">At least 8 characters. Not used for RADIUS accounts.</p></div></div><div class="form-actions"><button type="submit">＋ Add administrator</button></div></form></section><section class="card"><div class="card-head"><div><h2>Console users</h2><p>Account actions take effect immediately.</p></div><span class="badge quiet">{{len .Users}} users</span></div>{{if .Users}}<div class="table-wrap"><table><thead><tr><th>Username</th><th>Authentication</th><th>Actions</th></tr></thead><tbody>{{range .Users}}<tr><td><strong>{{.Username}}</strong></td><td><span class="badge quiet">{{.Mode}}</span></td><td><div class="actions"><form action="/admin/end" method="post" onsubmit="return confirm('End all sessions for this administrator?')"><input type="hidden" name="id" value="{{.ID}}"><button class="secondary small" type="submit">End sessions</button></form><form action="/admin/delete" method="post" onsubmit="return confirm('Permanently delete this administrator?')"><input type="hidden" name="id" value="{{.ID}}"><button class="danger small" type="submit">Delete</button></form></div></td></tr>{{end}}</tbody></table></div>{{else}}<div class="empty"><strong>No administrators found</strong>Create an account above.</div>{{end}}</section><script>(function(){var mode=document.getElementById('admin_mode'),field=document.getElementById('admin-password-field'),pw=document.getElementById('admin_password');function update(){var local=mode.value==='local';field.hidden=!local;pw.required=local}mode.addEventListener('change',update);update()})()</script></main></div>{{end}}` + base

// Statistics consumes the grouped, daily and inventory values already supplied by
// the stats handler in extra.go. Additional bucket granularity can be wired there.
const statsT = `{{define "body"}}<div class="app">{{template "nav" "stats"}}<main class="main">{{template "top" "Statistics"}}<header class="pagehead"><p class="eyebrow">Insights</p><h1>Statistics</h1><p>Operational activity in UTC. Events recorded before collection was enabled are not backfilled.</p></header><div class="actions" style="margin-bottom:20px" aria-label="Time range"><a class="button {{if eq .Period "24h"}}secondary{{else}}ghost{{end}}" href="/stats?period=24h">24 hours</a><a class="button {{if eq .Period "7d"}}secondary{{else}}ghost{{end}}" href="/stats?period=7d">7 days</a><a class="button {{if eq .Period "30d"}}secondary{{else}}ghost{{end}}" href="/stats?period=30d">30 days</a><a class="button {{if eq .Period "90d"}}secondary{{else}}ghost{{end}}" href="/stats?period=90d">90 days</a></div>{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}<div class="grid three"><section class="card"><div class="stat-label">Firewalls</div><div class="stat">{{.Firewalls}}</div><span class="badge quiet">Configured gateways</span></section><section class="card"><div class="stat-label">Manual identities</div><div class="stat">{{.Manual}}</div><span class="badge quiet">Pinned overrides</span></section><section class="card"><div class="stat-label">Tracked mappings</div><div class="stat">{{.Tracked}}</div><span class="badge good">Current inventory</span></section></div><div class="grid two section"><section class="card"><div class="card-head"><div><h2>Events by type</h2><p>Outcomes across the selected range.</p></div></div>{{if .Grouped}}<div class="table-wrap"><table><thead><tr><th>Operation</th><th>Outcome</th><th>Events</th></tr></thead><tbody>{{range .Grouped}}<tr><td><code>{{.Kind}}</code></td><td><span class="badge quiet">{{.Outcome}}</span></td><td>{{.Count}}</td></tr>{{end}}</tbody></table></div>{{else}}<div class="empty"><strong>No events recorded</strong>Activity will appear after operations are performed.</div>{{end}}</section><section class="card"><div class="card-head"><div><h2>Activity timeline</h2><p>Recorded events per day · UTC.</p></div></div>{{if .Daily}}<div class="stack">{{range .Daily}}<div class="chart-row" style="display:grid;grid-template-columns:90px 1fr 36px;align-items:center;gap:12px"><time class="muted">{{.Day}}</time><div class="chart-track" style="height:9px;border-radius:20px;background:#24364f;overflow:hidden"><div class="chart-bar" data-count="{{.Count}}" style="width:0;height:100%;border-radius:20px;background:linear-gradient(90deg,#358bd8,#38d9d0)"></div></div><strong>{{.Count}}</strong></div>{{end}}</div>{{else}}<div class="empty"><strong>No timeline data</strong>Activity will appear once events are recorded.</div>{{end}}</section></div><section class="card"><div class="card-head"><div><h2>Recent events</h2><p>Latest recorded operations in the selected range.</p></div></div>{{if .Recent}}<div class="table-wrap"><table><thead><tr><th>Time · UTC</th><th>Operation</th><th>Outcome</th><th>Detail</th></tr></thead><tbody>{{range .Recent}}<tr><td class="muted">{{.Created}}</td><td><code>{{.Kind}}</code></td><td>{{.Outcome}}</td><td class="status">{{.Detail}}</td></tr>{{end}}</tbody></table></div>{{else}}<div class="empty"><strong>No recent events</strong>There is nothing to display in this range.</div>{{end}}</section><script>(function(){var bars=[].slice.call(document.querySelectorAll('.chart-bar'));var max=Math.max(1,...bars.map(function(b){return Number(b.dataset.count)||0}));bars.forEach(function(b){b.style.width=Math.max(3,Math.round((Number(b.dataset.count)||0)/max*100))+'%'})})()</script></main></div>{{end}}` + base

const configT = `{{define "body"}}<div class="app">{{template "nav" "config"}}<main class="main">{{template "top" "Configuration"}}<header class="pagehead"><p class="eyebrow">Portability</p><h1>Configuration</h1><p>Export a backup or import saved configuration. Treat exported files as sensitive.</p></header>{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}<div class="grid two"><section class="card"><div class="card-head"><div><h2>Export configuration</h2><p>Download a backup for migration or safekeeping.</p></div><span class="badge">Backup</span></div><p class="muted">Store the exported file securely; it may include credentials or shared secrets.</p><div class="form-actions"><a class="button" href="/config/export">↓ Export configuration</a></div></section><section class="card"><div class="card-head"><div><h2>Import configuration</h2><p>Restore a previously exported configuration file.</p></div><span class="badge warn">Caution</span></div><form action="/config/import" method="post" enctype="multipart/form-data" onsubmit="return confirm('Import configuration from this file? Existing settings may be replaced.')"><div class="field"><label for="config-file">Configuration file</label><input id="config-file" type="file" name="file" accept=".json,application/json" required></div><div class="form-actions"><button class="secondary" type="submit">↑ Import configuration</button></div></form></section></div></main></div>{{end}}` + base
